use anyhow::{bail, ensure, Context, Result};
use large_text_core::{file_reader::{detect_encoding,FileReader},line_indexer::LineIndexer,search_engine::{SearchEngine,SearchMessage,SearchType}};
use std::{collections::{BTreeMap,BTreeSet},fs::File,io::{Read,Write},path::{Path,PathBuf},sync::{Arc,atomic::{AtomicBool,Ordering},mpsc}};

struct Options{values:BTreeMap<String,String>,flags:BTreeSet<String>}
impl Options{
 fn parse(args:&[String])->Result<Self>{let mut values=BTreeMap::new();let mut flags=BTreeSet::new();let mut at=0;while at<args.len(){let key=&args[at];if ["--regex","--line-numbers","--case-sensitive","--count-only"].contains(&key.as_str()){ensure!(flags.insert(key.clone()),"duplicate option");at+=1;}else{ensure!(["--file","--start","--end","--count","--pattern","--context","--max-output-bytes"].contains(&key.as_str()),"unknown option");let value=args.get(at+1).context("missing option value")?;ensure!(values.insert(key.clone(),value.clone()).is_none(),"duplicate option");at+=2;}}Ok(Self{values,flags})}
 fn required(&self,key:&str)->Result<&str>{self.values.get(key).map(String::as_str).context("missing required option")}
 fn number(&self,key:&str)->Result<Option<usize>>{self.values.get(key).map(|v|v.parse::<usize>().context("invalid unsigned option")).transpose()}
 fn flag(&self,key:&str)->bool{self.flags.contains(key)}
}
struct Output{writer:std::io::BufWriter<std::io::Stdout>,used:usize,limit:usize}
impl Write for Output{fn write(&mut self,bytes:&[u8])->std::io::Result<usize>{if self.used.checked_add(bytes.len()).is_none_or(|v|v>self.limit){return Err(std::io::Error::other("output_limit_exceeded"));}let n=self.writer.write(bytes)?;self.used+=n;Ok(n)}fn flush(&mut self)->std::io::Result<()>{self.writer.flush()}}
fn reader(path:&Path)->Result<Option<FileReader>>{let mut file=File::open(path).context("file_open_failed")?;if file.metadata()?.len()==0{return Ok(None);}let mut head=vec![0;8192];let size=file.read(&mut head)?;head.truncate(size);for _ in 0..3{if !matches!(std::str::from_utf8(&head),Err(error) if error.error_len().is_none()){break;}let mut byte=[0];if file.read(&mut byte)?==0{break;}head.push(byte[0]);}Ok(Some(FileReader::new(path.to_owned(),detect_encoding(&head)).context("file_map_failed")?))}
fn line(reader:&FileReader,index:&LineIndexer,at:usize)->Option<String>{let(start,end)=index.get_line_with_reader(at,reader)?;let len=reader.len();if start>=len{return None;}let text=reader.get_chunk(start.min(len),end.min(len));Some(text.trim_end_matches(['\r','\n']).to_owned())}
fn execute(args:&[String])->Result<()>{
 let command=args.first().context("missing command")?;
 if command=="--capabilities"{println!("{}",r#"{"protocol":"large-text-cli-v1","version":"0.1.0","commands":["info","lines","search"],"output_limit":true}"#);return Ok(());}
 let options=Options::parse(&args[1..])?;let path=PathBuf::from(options.required("--file")?);let limit=options.number("--max-output-bytes")?.unwrap_or(262144);ensure!(limit>=1024,"output budget too small");let mut out=Output{writer:std::io::BufWriter::new(std::io::stdout()),used:0,limit};
 let input=reader(&path)?;
 if command=="info"{if let Some(reader)=input{let mut index=LineIndexer::new();index.index_file(&reader);writeln!(out,"File: {}\nSize: {} bytes\nEncoding: {}\nEstimated lines: {}",path.display(),reader.len(),reader.encoding().name(),index.total_lines().saturating_sub(usize::from(reader.get_bytes(reader.len()-1,reader.len())==b"\n")))?;}else{writeln!(out,"File: {}\nSize: 0 bytes\nEncoding: UTF-8\nEstimated lines: 0",path.display())?;}out.flush()?;return Ok(());}
 if command=="lines"{let start=options.number("--start")?.context("missing start")?;ensure!(start>0,"start must be one-based");let end=if let Some(end)=options.number("--end")?{ensure!(end>=start,"end must not precede start");end}else{let count=options.number("--count")?.unwrap_or(50);ensure!(count>0,"count must be positive");start.checked_add(count-1).context("line range overflow")?};if let Some(reader)=input{let mut index=LineIndexer::new();index.index_file(&reader);for at in start-1..end{let Some(text)=line(&reader,&index,at)else{break;};if options.flag("--line-numbers"){writeln!(out,"{:>8} {}",at+1,text)?;}else{writeln!(out,"{text}")?;}}}out.flush()?;return Ok(());}
 if command!="search"{bail!("unknown command");}let query=options.required("--pattern")?;ensure!(!query.is_empty(),"empty search pattern");let context=options.number("--context")?.unwrap_or(0);
 let Some(reader)=input else{writeln!(out,"Found 0 matches\nShowed 0 matches")?;out.flush()?;return Ok(());};let reader=Arc::new(reader);let mut index=LineIndexer::new();index.index_file(&reader);let mut engine=SearchEngine::new();engine.set_query(query.to_owned(),options.flag("--regex"),options.flag("--case-sensitive"));let cancel=Arc::new(AtomicBool::new(false));let(tx,rx)=mpsc::sync_channel(1024);engine.count_matches(Arc::clone(&reader),tx,Arc::clone(&cancel));let mut total=0usize;let mut count_done=false;while let Ok(message)=rx.recv(){match message{SearchMessage::CountResult(n)=>total=total.checked_add(n).context("match count overflow")?,SearchMessage::Done(SearchType::Count)=>{count_done=true;break;},SearchMessage::Error(e)=>bail!("search_failed: {e}"),_=>{}}}ensure!(count_done,"search worker ended without count receipt");writeln!(out,"Found {total} matches")?;
 if total==0||options.flag("--count-only"){writeln!(out,"Showed 0 matches")?;out.flush()?;return Ok(());}
 let(tx,rx)=mpsc::sync_channel(1024);engine.fetch_matches(Arc::clone(&reader),tx,0,50,Arc::clone(&cancel));let mut shown=0usize;let mut fetch_done=false;while let Ok(message)=rx.recv(){match message{SearchMessage::ChunkResult(chunk)=>{for item in chunk.matches{if shown==50{break;}shown+=1;let at=index.find_line_at_offset(item.byte_offset);if context>0{writeln!(out,"--- match #{shown} @ line {} ---",at+1)?;for pos in at.saturating_sub(context)..=at.saturating_add(context){if let Some(text)=line(&reader,&index,pos){writeln!(out,"{:>8} {}",pos+1,text)?;}else{break;}}}else if let Some(text)=line(&reader,&index,at){writeln!(out,"{:>8} {}",at+1,text)?;}}},SearchMessage::Done(SearchType::Fetch)=>{fetch_done=true;break;},SearchMessage::Error(e)=>bail!("search_failed: {e}"),_=>{}}}cancel.store(true,Ordering::Relaxed);ensure!(fetch_done,"search worker ended without fetch receipt");writeln!(out,"Showed {shown} matches")?;out.flush()?;Ok(())
}
fn main(){let args=std::env::args().skip(1).collect::<Vec<_>>();if let Err(error)=execute(&args){eprintln!("{error:#}");std::process::exit(2);}}
